using namespace std;

int main() {
    string board;
    cin >> board;
    int answer = 0;
    // Pieces stay on their index mod 3; each chain collects every coin right of its leftmost piece.
    for (int residue = 0; residue < 3; residue++) {
        bool started = false;
        for (size_t i = residue; i < board.size(); i += 3) {
            if (board[i] == 'T') started = true;
