import java.util.*;

public class Main {
    public static void main(String[] args) {
        String board = new Scanner(System.in).next();
        int answer = 0;
        // Pieces stay on their index mod 3; each chain collects every coin right of its leftmost piece.
        for (int residue = 0; residue < 3; residue++) {
            boolean started = false;
            for (int i = residue; i < board.length(); i += 3) {
                char c = board.charAt(i);
                if (c == 'T') started = true;
                else if (c == 'C' && started) answer++;
            }
        }
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var board string
	fmt.Scan(&board)
	answer := 0
	// Pieces stay on their index mod 3; each chain collects every coin right of its leftmost piece.
	for residue := 0; residue < 3; residue++ {
		started := false
		for i := residue; i < len(board); i += 3 {
			if board[i] == 'T' {
				started = true
			} else if board[i] == 'C' && started {
				answer++
			}
		}
	}
	fmt.Println(answer)
}
